-- reports/local-unit-in-district
-- Whether a local unit belongs to a district (the optional local-unit select).
--
-- Parameters, with the example values used to render this file:
--   $1 = "0199c8a0-0000-7000-8000-00000000000a"
--   $2 = "0199c8a0-0000-7000-8000-00000000000a"
--   $3 = 1
--
-- Generated by `pnpm db:queries` from lib/db/queries/reports.ts. Do not edit by hand.

select "id"
from "local_units"
where ("local_units"."id" = $1
  and "local_units"."district_id" = $2)
limit $3;
